<script setup>
import {computed,ref,watch} from 'vue'
import SimulationControls from './SimulationControls.vue'
import {puzzleGoal,puzzleExamples,puzzleParts,puzzleHeuristic,solvePuzzle,validatePuzzle} from '../services/heuristic-puzzle.mjs'
const exampleId=ref('source'),initial=ref([...puzzleExamples[0].board]),mode=ref('manhattan'),step=ref(0),input=ref(initial.value.join(' ')),error=ref(''),results=ref(null)
watch(exampleId,()=>{initial.value=[...puzzleExamples.find(e=>e.id===exampleId.value).board];input.value=initial.value.join(' ');results.value=null;error.value=''})
const solution=computed(()=>solvePuzzle(initial.value,mode.value))
const board=computed(()=>solution.value.path[step.value]||initial.value)
const parts=computed(()=>puzzleParts(board.value)),manhattan=computed(()=>puzzleHeuristic(board.value)),misplaced=computed(()=>puzzleHeuristic(board.value,'misplaced'))
const resetKey=computed(()=>JSON.stringify([initial.value,mode.value]))
watch(resetKey,()=>{step.value=0})
function apply(){try{const a=input.value.trim().split(/[\s,;]+/).map(Number);validatePuzzle(a);initial.value=a;error.value='';results.value=null}catch(e){error.value=e.message}}
function compare(){results.value=['zero','misplaced','manhattan'].map(m=>({mode:m,...solvePuzzle(initial.value,m)}))}
const names={zero:'h = 0',misplaced:'Số ô sai',manhattan:'Manhattan'}
</script>

<template>
<figure class="lab puzzle-lab" aria-label="Tính heuristic và xem lời giải A sao cho trò đẩy ô số">
  <div class="puzzle-settings"><label>Trạng thái đầu<select v-model="exampleId"><option v-for="e in puzzleExamples" :key="e.id" :value="e.id">{{ e.title }}</option></select></label><label>Heuristic của A*<select v-model="mode"><option value="manhattan">Tổng khoảng cách Manhattan</option><option value="misplaced">Số ô sai vị trí</option><option value="zero">h = 0 · UCS</option></select></label></div>
  <p>Di chuyển bốn hướng, mỗi lần trượt một ô số vào ô trống tốn 1. Không tính ô trống trong heuristic. Hàng và cột được đánh số từ 0.</p>
  <p class="puzzle-status" role="status"><template v-if="solution.status==='success'">A* tìm được lời giải {{ solution.cost }} bước. Đã mở rộng {{ solution.expanded }} nút và sinh {{ solution.generated }} bản ghi, tính cả nút đầu.</template><template v-else-if="solution.status==='budget'">Đã chạm giới hạn 20.000 lần mở rộng để giữ trình duyệt phản hồi tốt. Chưa kết luận vô nghiệm. Hãy dùng Manhattan hoặc chọn bài nhỏ.</template><template v-else-if="solution.status==='unsolvable'">Số nghịch thế lẻ. Trạng thái này không thể đi tới đích đã chọn trên bảng 3 × 3.</template><template v-else>Không tìm được lời giải.</template></p>
  <p v-if="solution.status==='success'">Thanh điều khiển phát lại đường đi trả về. Mỗi bước là một hành động trượt ô, không phải một lần mở rộng biên. Vết chạy biên và mã A* nằm trong mô phỏng đồ thị của bài.</p>
  <SimulationControls v-model="step" :max="Math.max(0,solution.path.length-1)" :reset-key="resetKey" label="Hành động"/>
  <div class="puzzle-boards"><section><h4>Trạng thái sau {{ step }} hành động</h4><div class="puzzle-board" role="img" :aria-label="board.map(v=>v||'Trống').join(', ')"><span v-for="(v,i) in board" :key="i" :class="{blank:v===0,wrong:v!==0&&v!==i}">{{ v||'·' }}</span></div></section><section><h4>Đích cố định</h4><div class="puzzle-board goal-board" role="img" aria-label="Đích: Trống, 1, 2, 3, 4, 5, 6, 7, 8"><span v-for="(v,i) in puzzleGoal" :key="i" :class="{blank:v===0}">{{ v||'·' }}</span></div></section></div>
  <div class="puzzle-values"><p>Số ô sai = {{ misplaced }}.</p><p>Manhattan = {{ parts.map(p=>p.distance).join(' + ') }} = {{ manhattan }}.</p><p>g = {{ step }} · h đã chọn = {{ puzzleHeuristic(board,mode) }} · f = {{ step+puzzleHeuristic(board,mode) }}.</p></div>
  <details open><summary>Khoảng cách của từng ô số</summary><ul class="puzzle-parts"><li v-for="p in parts" :key="p.tile"><strong>Ô {{ p.tile }}</strong><span>({{ p.row }}, {{ p.col }}) → ({{ p.goalRow }}, {{ p.goalCol }})</span><span>{{ p.vertical }} dọc + {{ p.horizontal }} ngang = {{ p.distance }}</span></li></ul></details>
  <div class="puzzle-compare"><button type="button" @click="compare">So sánh ba heuristic trên cùng đầu vào</button><p>Giới hạn 20.000 lần mở rộng cho mỗi lượt. Mỗi lần so sánh dùng cùng thứ tự láng giềng và phá hòa theo thứ tự thêm. Đếm số thao tác, không dùng thời gian máy làm kết luận tổng quát.</p><ul v-if="results"><li v-for="r in results" :key="r.mode">{{ names[r.mode] }}: {{ r.status==='success'?'Chi phí '+r.cost:r.status==='budget'?'Chạm giới hạn':r.status==='unsolvable'?'Không thể tới đích':'Không tìm được' }}. {{ r.expanded }} lần mở rộng · {{ r.generated }} bản ghi được sinh.</li></ul></div>
  <details class="puzzle-edit"><summary>Nhập một trạng thái 3 × 3 khác</summary><label>Chín số theo hàng, dùng 0 cho ô trống<input v-model="input" type="text" inputmode="numeric"/></label><button type="button" @click="apply">Áp dụng và đặt lại</button><p v-if="error" role="alert">{{ error }}</p></details>
</figure>
</template>

<style scoped>
.puzzle-lab{min-width:0}.puzzle-settings{display:grid;grid-template-columns:1fr 1fr;gap:12px}.puzzle-lab label{display:grid;gap:6px}.puzzle-lab :is(select,button,input){min-height:44px;max-width:100%;box-sizing:border-box;border:1px solid var(--control);border-radius:var(--radius);padding:8px;background:var(--paper);color:var(--ink);font:var(--fs-small)/1.6 var(--font-ui)}.puzzle-lab select,.puzzle-edit input{width:100%}.puzzle-lab :is(button,input,select):focus-visible{outline:3px solid var(--tim);outline-offset:3px}.puzzle-lab p,.puzzle-lab li,.puzzle-lab label{font:var(--fs-small)/1.7 var(--font-ui)}.puzzle-status,.puzzle-values{padding:12px;background:var(--tim-soft);border-left:3px solid var(--tim);overflow-wrap:anywhere}.puzzle-boards{display:grid;grid-template-columns:1fr 1fr;gap:20px}.puzzle-boards h4{font:600 var(--fs-ui)/1.6 var(--font-ui);margin:0 0 10px}.puzzle-board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;max-width:240px;aspect-ratio:1}.puzzle-board span{display:flex;align-items:center;justify-content:center;border:1px solid var(--control);border-radius:var(--radius);font:600 28px var(--font-ui);background:var(--paper);color:var(--ink)}.puzzle-board .wrong{border-color:var(--tim);background:var(--tim-soft)}.puzzle-board .blank{border-style:dashed;color:var(--ink-2);background:transparent}.puzzle-parts{display:grid;grid-template-columns:1fr 1fr;gap:8px;list-style:none;padding:0!important}.puzzle-parts li{display:grid;gap:3px;border-bottom:1px solid var(--rule);padding:8px 0}.puzzle-compare{margin-top:20px}.puzzle-lab details{margin-top:16px;font-size:var(--fs-small)}.puzzle-lab summary{cursor:pointer;min-height:44px;line-height:1.7}.puzzle-lab button{cursor:pointer}.puzzle-edit button{margin-top:10px}@media(max-width:600px){.puzzle-settings,.puzzle-boards,.puzzle-parts{grid-template-columns:minmax(0,1fr)}.puzzle-lab{padding:12px}.puzzle-board{max-width:210px}}
</style>
